## FULL ROUTE IMPLEMENTATION: app/routes/app.quizzes.$id.questions.tsx

```tsx
export async function loader({ request, params }: LoaderFunctionArgs) {
  const { session } = await authenticate.admin(request);
  const quiz = await db.quiz.findFirst({
    where: { id: params.id, shop: session.shop },
    include: {
      questions: {
        orderBy: { position: "asc" },
        include: { answers: { orderBy: { position: "asc" } } }
      }
    },
  });
  if (!quiz) throw new Response("Not found", { status: 404 });
  return json({ quiz });
}

export async function action({ request, params }: ActionFunctionArgs) {
  const { session } = await authenticate.admin(request);
  const formData = await request.formData();
  const intent = formData.get("intent") as string;
  const shop = session.shop;
  const quizId = params.id!;

  // Verify quiz belongs to shop
  const quiz = await db.quiz.findFirst({ where: { id: quizId, shop } });
  if (!quiz) return json({ error: "Not found" }, { status: 404 });

  try {
    switch (intent) {
      case "addQuestion": {
        const type = formData.get("type") as QuestionType;
        const maxPosition = await db.question.aggregate({
          where: { quizId }, _max: { position: true }
        });
        const position = (maxPosition._max.position ?? -1) + 1;
        const defaultSettings = getDefaultSettings(type);
        const question = await db.question.create({
          data: { quizId, type, title: "New question", required: true, position,
            settings: JSON.stringify(defaultSettings), logic: "[]" },
          include: { answers: true },
        });
        // Auto-create default answers for choice types
        if (["multiple-choice", "image-choice", "dropdown"].includes(type)) {
          await db.answer.createMany({
            data: [
              { questionId: question.id, text: "Option 1", position: 0, score: 0, productTags: "[]", metadata: "{}" },
              { questionId: question.id, text: "Option 2", position: 1, score: 0, productTags: "[]", metadata: "{}" },
            ]
          });
        }
        return json({ success: true, message: "Question added", questionId: question.id });
      }
      case "updateQuestion": {
        const id = formData.get("id") as string;
        const title = formData.get("title") as string;
        const description = formData.get("description") as string;
        const required = formData.get("required") === "true";
        const settings = formData.get("settings") as string;
        await db.question.updateMany({
          where: { id, quizId },
          data: { title, description: description || null, required, settings },
        });
        return json({ success: true, message: "Question updated" });
      }
      case "deleteQuestion": {
        const id = formData.get("id") as string;
        await db.question.deleteMany({ where: { id, quizId } });
        // Recompact positions
        const remaining = await db.question.findMany({ where: { quizId }, orderBy: { position: "asc" } });
        await db.$transaction(remaining.map((q, i) => db.question.update({ where: { id: q.id }, data: { position: i } })));
        return json({ success: true, message: "Question deleted" });
      }
      case "reorderQuestions": {
        const orderedIds = JSON.parse(formData.get("orderedIds") as string) as string[];
        await db.$transaction(orderedIds.map((id, position) =>
          db.question.updateMany({ where: { id, quizId }, data: { position } })
        ));
        return json({ success: true });
      }
      case "addAnswer": {
        const questionId = formData.get("questionId") as string;
        const maxPos = await db.answer.aggregate({ where: { questionId }, _max: { position: true } });
        await db.answer.create({
          data: { questionId, text: "New option", position: (maxPos._max.position ?? -1) + 1,
            score: 0, productTags: "[]", metadata: "{}" }
        });
        return json({ success: true, message: "Answer added" });
      }
      case "updateAnswer": {
        const id = formData.get("id") as string;
        const text = formData.get("text") as string;
        const score = parseInt(formData.get("score") as string) || 0;
        const productTags = formData.get("productTags") as string;
        const imageUrl = formData.get("imageUrl") as string;
        await db.answer.update({ where: { id }, data: { text, score, productTags, imageUrl: imageUrl || null } });
        return json({ success: true });
      }
      case "deleteAnswer": {
        const id = formData.get("id") as string;
        const answer = await db.answer.findUnique({ where: { id }, select: { questionId: true } });
        if (answer) {
          await db.answer.delete({ where: { id } });
          const remaining = await db.answer.findMany({ where: { questionId: answer.questionId }, orderBy: { position: "asc" } });
          await db.$transaction(remaining.map((a, i) => db.answer.update({ where: { id: a.id }, data: { position: i } })));
        }
        return json({ success: true });
      }
      default:
        return json({ error: "Unknown action" }, { status: 400 });
    }
  } catch (error) {
    return json({ error: error instanceof Error ? error.message : "An error occurred" }, { status: 500 });
  }
}

function getDefaultSettings(type: QuestionType): object {
  switch (type) {
    case "multiple-choice": return { allowMultiple: false, maxSelections: 1, randomizeOrder: false };
    case "image-choice": return { imageSize: "medium", showLabels: true, allowMultiple: false };
    case "slider": return { min: 0, max: 10, step: 1, minLabel: "Low", maxLabel: "High", showValue: true };
    case "text-input": return { placeholder: "Type your answer...", maxLength: 500, multiline: false };
    case "email": return { placeholder: "your@email.com", label: "Email address", collectName: false, consentText: "" };
    case "date": return { format: "MM/DD/YYYY" };
    case "dropdown": return { placeholder: "Select an option", searchable: false };
    case "rating": return { maxRating: 5, icon: "star", showLabels: true, lowLabel: "Poor", highLabel: "Excellent" };
    default: return {};
  }
}
