## IMAGE UPLOAD PATTERN (For image-choice type)

```typescript
// Shopify staged upload → Google Storage → confirm
async function uploadQuestionImage(admin: any, file: File): Promise<string> {
  // 1. Request staged upload URL
  const stagedResponse = await admin.graphql(`
    mutation stagedUploadsCreate($input: [StagedUploadInput!]!) {
      stagedUploadsCreate(input: $input) {
        stagedTargets { url resourceUrl parameters { name value } }
        userErrors { field message }
      }
    }
  `, { variables: { input: [{ filename: file.name, mimeType: file.type, resource: "FILE", fileSize: String(file.size) }] } });
  const { data } = await stagedResponse.json();
  const target = data.stagedUploadsCreate.stagedTargets[0];
  // 2. Upload to Google Storage
  const formData = new FormData();
  target.parameters.forEach(({ name, value }: { name: string; value: string }) => formData.append(name, value));
  formData.append("file", file);
  await fetch(target.url, { method: "POST", body: formData });
  return target.resourceUrl;
}
```

