## DRAG-AND-DROP REORDER PATTERN

```tsx
// Optimistic reorder: update UI immediately, save to server
function useQuestionReorder(questions: Question[], submit: Function) {
  const [orderedIds, setOrderedIds] = useState(questions.map(q => q.id));

  const handleDragEnd = useCallback((result: DropResult) => {
    if (!result.destination) return;
    const newOrder = Array.from(orderedIds);
    const [moved] = newOrder.splice(result.source.index, 1);
    newOrder.splice(result.destination.index, 0, moved);
    setOrderedIds(newOrder); // Optimistic update
    submit({ intent: "reorderQuestions", orderedIds: JSON.stringify(newOrder) }, { method: "POST" });
  }, [orderedIds, submit]);

  return { orderedIds, handleDragEnd };
}
```

