## LOGIC RULE SCHEMA

```typescript
// Stored in Question.logic as JSON array of LogicRule[]
interface LogicCondition {
  questionId: string;
  operator: "equals" | "not_equals" | "contains" | "greater_than" | "less_than";
  value: string | number;
}

interface LogicRule {
  type: "show-if" | "hide-if" | "skip-to" | "score-add" | "tag-add";
  conditions: LogicCondition[];
  conditionOperator: "AND" | "OR";
  action: {
    questionId?: string;  // for skip-to, show-if, hide-if
    score?: number;       // for score-add
    tag?: string;         // for tag-add
  };
}

// Answer.nextQuestionId: direct branch override (simpler than rules)
// If set, always go to that question regardless of logic rules
```

## PURE EVALUATION FUNCTION (Server-side, no side effects)

```typescript
// app/utils/logic-engine.ts
export function evaluateConditions(
  conditions: LogicCondition[],
  operator: "AND" | "OR",
  responses: Record<string, string | string[] | number>
): boolean {
  const results = conditions.map(c => {
    const response = responses[c.questionId];
    switch (c.operator) {
      case "equals":       return String(response) === String(c.value);
      case "not_equals":   return String(response) !== String(c.value);
      case "contains":     return Array.isArray(response) ? response.includes(String(c.value)) : String(response).includes(String(c.value));
      case "greater_than": return Number(response) > Number(c.value);
      case "less_than":    return Number(response) < Number(c.value);
      default:             return false;
    }
  });
  return operator === "AND" ? results.every(Boolean) : results.some(Boolean);
}

export function getNextQuestionId(
  currentQuestion: { id: string; logic: string },
  selectedAnswers: { nextQuestionId?: string | null },
  allResponses: Record<string, string | string[] | number>,
  allQuestions: Array<{ id: string; position: number }>
): string | null {
  // 1. Direct answer branch (highest priority)
  if (selectedAnswers.nextQuestionId) return selectedAnswers.nextQuestionId;

  // 2. Evaluate logic rules
  const rules: LogicRule[] = JSON.parse(currentQuestion.logic || "[]");
  for (const rule of rules) {
    if (rule.type === "skip-to" && evaluateConditions(rule.conditions, rule.conditionOperator, allResponses)) {
      return rule.action.questionId ?? null;
    }
  }

  // 3. Default: next in position order
  const sorted = [...allQuestions].sort((a, b) => a.position - b.position);
  const currentIndex = sorted.findIndex(q => q.id === currentQuestion.id);
  return sorted[currentIndex + 1]?.id ?? null; // null = quiz complete
}

export function accumulateTagsAndScores(
  rules: LogicRule[],
  responses: Record<string, string | string[] | number>
): { tags: string[]; scoreBonus: number } {
  let tags: string[] = [];
  let scoreBonus = 0;
  for (const rule of rules) {
    if (!evaluateConditions(rule.conditions, rule.conditionOperator, responses)) continue;
    if (rule.type === "tag-add" && rule.action.tag) tags.push(rule.action.tag);
    if (rule.type === "score-add" && rule.action.score) scoreBonus += rule.action.score;
  }
  return { tags: [...new Set(tags)], scoreBonus };
}
```

## CYCLE DETECTION (DAG Validation)

```typescript
// Validate quiz logic graph is a DAG (Directed Acyclic Graph)
export function detectCycles(questions: Array<{ id: string; logic: string }>,
  answers: Array<{ id: string; questionId: string; nextQuestionId: string | null }>
): string[] {
  const graph: Record<string, string[]> = {};
  for (const q of questions) {
    graph[q.id] = [];
    const rules: LogicRule[] = JSON.parse(q.logic || "[]");
    for (const rule of rules) {
      if (rule.action.questionId) graph[q.id].push(rule.action.questionId);
    }
  }
  for (const a of answers) {
    if (a.nextQuestionId) {
      graph[a.questionId] = [...(graph[a.questionId] || []), a.nextQuestionId];
    }
  }
  const visited = new Set<string>(); const inStack = new Set<string>();
  const cycles: string[] = [];
  function dfs(node: string) {
    visited.add(node); inStack.add(node);
    for (const neighbor of graph[node] || []) {
      if (!visited.has(neighbor)) dfs(neighbor);
      else if (inStack.has(neighbor)) cycles.push(`${node} → ${neighbor}`);
    }
    inStack.delete(node);
  }
  for (const q of questions) if (!visited.has(q.id)) dfs(q.id);
  return cycles;
}
```

