```typescript
// app/services/recommendation.server.ts
export interface ScoredProduct {
  productGid: string; title: string; imageUrl: string | null; handle: string;
  priceMin: number; priceMax: number;
  totalScore: number; matchedTags: string[]; matchPercentage: number;
}

export function scoreProducts(
  responseTags: string[],
  productMappings: Array<{ productGid: string; title: string; imageUrl: string | null; handle: string; tags: string; score: number; collections: string; priceMin: number; priceMax: number; }>,
  mode: "tag-match" | "point-based" | "hybrid",
  responseScore?: number
): ScoredProduct[] {
  const normalizedResponseTags = responseTags.map(t => t.toLowerCase().trim());

  return productMappings.map(pm => {
    const productTags = (JSON.parse(pm.tags) as string[]).map(t => t.toLowerCase().trim());
    const matchedTags = productTags.filter(t => normalizedResponseTags.includes(t));
    const tagScore = matchedTags.length * 10;
    const matchPercentage = productTags.length > 0 ? Math.round((matchedTags.length / productTags.length) * 100) : 0;

    let totalScore: number;
    switch (mode) {
      case "tag-match":    totalScore = tagScore; break;
      case "point-based":  totalScore = pm.score; break;
      case "hybrid":       totalScore = tagScore + pm.score; break;
    }
    return { productGid: pm.productGid, title: pm.title, imageUrl: pm.imageUrl, handle: pm.handle,
      priceMin: pm.priceMin, priceMax: pm.priceMax, totalScore, matchedTags, matchPercentage };
  })
  .filter(p => p.totalScore > 0)
  .sort((a, b) => b.totalScore - a.totalScore || b.matchPercentage - a.matchPercentage || a.priceMin - b.priceMin);
}

export async function getRecommendations(
  shop: string, quizId: string, responseTags: string[], limit: number = 4
): Promise<ScoredProduct[]> {
  const mappings = await db.productMapping.findMany({
    where: { shop, status: "active" },
  });
  const scored = scoreProducts(responseTags, mappings, "hybrid");

  // GUARANTEE: Always return something
  if (scored.length === 0) {
    const fallback = await db.productMapping.findMany({
      where: { shop, status: "active" }, orderBy: { score: "desc" }, take: limit,
    });
    return fallback.map(pm => ({
      productGid: pm.productGid, title: pm.title, imageUrl: pm.imageUrl, handle: pm.handle,
      priceMin: pm.priceMin, priceMax: pm.priceMax, totalScore: pm.score, matchedTags: [], matchPercentage: 0
    }));
  }
  return scored.slice(0, limit);
}
```

