  let cursor: string | null = null;
  let synced = 0;
  const activeGids = new Set<string>();

  do {
    const response = await admin.graphql(PRODUCTS_QUERY, { variables: { first: 250, after: cursor } });
    const { data } = await response.json();
    const { edges, pageInfo } = data.products;

    for (const { node: product } of edges) {
      activeGids.add(product.id);
      await db.productMapping.upsert({
        where: { shop_productGid: { shop, productGid: product.id } },
        update: {
          title: product.title, handle: product.handle, status: "active",
          imageUrl: product.featuredImage?.url ?? null,
          tags: JSON.stringify(product.tags),
          collections: JSON.stringify(product.collections.edges.map((e: any) => e.node.id)),
          priceMin: parseFloat(product.priceRangeV2.minVariantPrice.amount),
          priceMax: parseFloat(product.priceRangeV2.maxVariantPrice.amount),
          syncedAt: new Date(),
        },
        create: {
          shop, productGid: product.id, title: product.title, handle: product.handle,
          imageUrl: product.featuredImage?.url ?? null, status: "active",
          tags: JSON.stringify(product.tags), score: 0,
          collections: JSON.stringify(product.collections.edges.map((e: any) => e.node.id)),
          priceMin: parseFloat(product.priceRangeV2.minVariantPrice.amount),
          priceMax: parseFloat(product.priceRangeV2.maxVariantPrice.amount),
        },
      });
      synced++;
    }
    cursor = pageInfo.hasNextPage ? pageInfo.endCursor : null;
  } while (cursor);

  // Soft-delete products no longer in Shopify
  const archived = await db.productMapping.updateMany({
    where: { shop, productGid: { notIn: [...activeGids] }, status: "active" },
    data: { status: "archived" },
  });
  return { synced, archived: archived.count };
}
```

## COLLECTION-BASED FILTERING

```typescript
export function filterByCollections(
  scored: ScoredProduct[], productMappings: any[],
  requiredCollectionGids: string[]
): ScoredProduct[] {
  if (!requiredCollectionGids.length) return scored;
  return scored.filter(p => {
    const pm = productMappings.find(m => m.productGid === p.productGid);
    const collections = JSON.parse(pm?.collections ?? "[]") as string[];
    return requiredCollectionGids.some(c => collections.includes(c));
  });
}
```

## SELF-VALIDATION CHECKLIST
- [ ] Product GIDs stored in full format: "gid://shopify/Product/XXX"
- [ ] Tags comparison is case-insensitive
- [ ] Fallback always returns ≥1 product (never empty array)
- [ ] Soft-delete products removed from Shopify (status: "archived")
- [ ] Large catalog sync (1000+) paginates correctly — 250/page
- [ ] Sync uses upsert — safe to run multiple times
- [ ] ProductMapping scoped to shop (not per-quiz)
- [ ] Price data kept in sync (priceMin, priceMax)
- [ ] npm run typecheck passes on recommendation.server.ts

## NEVER
- Never return empty recommendations — always use fallback
- Never sync products without pagination
- Never compare tags case-sensitively
- Never hard-delete ProductMappings — soft delete (status: "archived")
- Never run full sync synchronously for large catalogs — use background job
- Never expose pricing calculations to the client — server-side only
