// app/services/analytics.server.ts
export async function getQuizFunnel(quizId: string, shop: string, dateRange: { from: Date; to: Date }) {
  const where = { quizId, shop, createdAt: { gte: dateRange.from, lte: dateRange.to } };

  const [started, completed, addedToCart, purchased] = await db.$transaction([
    db.analyticsEvent.count({ where: { ...where, eventType: "quiz_started" } }),
    db.analyticsEvent.count({ where: { ...where, eventType: "quiz_completed" } }),
    db.analyticsEvent.count({ where: { ...where, eventType: "added_to_cart" } }),
    db.analyticsEvent.count({ where: { ...where, eventType: "purchase" } }),
  ]);

  return {
    started,
    completed,       completionRate:    started > 0 ? Math.round((completed / started) * 100) : 0,
    addedToCart,     cartRate:          completed > 0 ? Math.round((addedToCart / completed) * 100) : 0,
    purchased,       purchaseRate:      addedToCart > 0 ? Math.round((purchased / addedToCart) * 100) : 0,
    overallConvRate: started > 0 ? Math.round((purchased / started) * 100) : 0,
  };
}

export async function getQuestionDropOff(quizId: string, shop: string) {
  const questionEvents = await db.analyticsEvent.groupBy({
    by: ["data"],
    where: { quizId, shop, eventType: "question_answered" },
    _count: { id: true },
  });

  const abandonedAt = await db.analyticsEvent.groupBy({
    by: ["data"],
    where: { quizId, shop, eventType: "quiz_abandoned" },
    _count: { id: true },
  });

  // Parse questionId from data JSON, aggregate per question
  return { questionEvents, abandonedAt };
}

export async function getRevenue(quizId: string, shop: string, dateRange: { from: Date; to: Date }) {
  const revenue = await db.analyticsEvent.aggregate({
    where: { quizId, shop, eventType: "purchase", createdAt: { gte: dateRange.from, lte: dateRange.to } },
    _sum: { revenue: true },
    _count: { id: true },
  });
  return { total: revenue._sum.revenue ?? 0, orders: revenue._count.id };
}
