```javascript
// extensions/quiz-widget/assets/quiz-widget.js
(function() {
  "use strict";
  const APP_URL = document.currentScript.dataset.appUrl || "";

  const State = { LOADING: "loading", ACTIVE: "active", COMPLETE: "complete", ERROR: "error" };

  class QuizSnapWidget {
    constructor(container) {
      this.container = container;
      this.slug = container.dataset.quizSlug;
      this.shop = container.dataset.shop;
      this.sessionId = this.getSessionId();
      this.state = State.LOADING;
      this.currentQuestionIndex = 0;
      this.responses = {};
      this.responseTags = [];
      this.init();
    }

    getSessionId() {
      let id = sessionStorage.getItem("qs_session");
      if (!id) { id = crypto.randomUUID(); sessionStorage.setItem("qs_session", id); }
      return id;
    }

    async init() {
      try {
        const [quizData, config] = await Promise.all([
          this.fetchQuiz(), this.fetchConfig()
        ]);
        this.quiz = quizData;
        this.config = config;
        this.render();
        this.trackEvent("quiz_started", { source: document.referrer ? "referral" : "direct" });
      } catch (e) {
        this.setState(State.ERROR);
      }
    }

    async fetchQuiz() {
      const cache = sessionStorage.getItem(`qs_quiz_${this.slug}`);
      if (cache) return JSON.parse(cache);
      const res = await fetch(`${APP_URL}/api/quiz/${this.slug}?shop=${this.shop}`);
      if (!res.ok) throw new Error("Quiz not found");
      const data = await res.json();
      sessionStorage.setItem(`qs_quiz_${this.slug}`, JSON.stringify(data));
      return data;
    }

    async fetchConfig() {
      const cache = localStorage.getItem(`qs_config_${this.shop}`);
      if (cache) { const { data, ts } = JSON.parse(cache); if (Date.now() - ts < 300000) return data; }
      const res = await fetch(`${APP_URL}/api/widget-config?shop=${this.shop}`);
      const data = await res.json();
      localStorage.setItem(`qs_config_${this.shop}`, JSON.stringify({ data, ts: Date.now() }));
      return data;
    }

    async submitResponse() {
      const res = await fetch(`${APP_URL}/api/submit`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ shop: this.shop, quizId: this.quiz.id, sessionId: this.sessionId, responses: this.responses, tags: this.responseTags }),
      });
      return res.json(); // { recommendations: [...], resultPage: {...} }
    }

    trackEvent(eventType, data = {}) {
      // Non-blocking — fire and forget
      fetch(`${APP_URL}/api/analytics`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ shop: this.shop, eventType, quizId: this.quiz?.id, sessionId: this.sessionId, data }),
      }).catch(() => {});
    }

    setState(newState) { this.state = newState; this.render(); }
    render() { /* Build DOM based on this.state */ }
  }

  // Initialize all widgets on page
  document.querySelectorAll("[data-quiz-slug]").forEach(el => new QuizSnapWidget(el));
})();
```

