  const body = await request.json().catch(() => null);
  const parsed = SubmitSchema.safeParse(body);
  if (!parsed.success) return apiError(parsed.error.message);

  const { shop, quizId, sessionId, responses, tags = [], email } = parsed.data;

  // Get recommendations
  const { getRecommendations } = await import("../services/recommendation.server");
  const recommendations = await getRecommendations(shop, quizId, tags);

  // Save response (non-blocking score calculation)
  await db.quizResponse.create({
    data: { quizId, shop, sessionId, email: email ?? null, answers: JSON.stringify(responses),
      recommendedProducts: JSON.stringify(recommendations.map(r => r.productGid)), completedAt: new Date() }
  });

  // Increment quiz completions counter
  await db.quiz.updateMany({ where: { id: quizId, shop }, data: { completions: { increment: 1 } } });

  return json({ recommendations, success: true }, { headers: cors });
}
