const EventSchema = z.object({
  shop: z.string().regex(shopRegex),
  eventType: z.enum(["quiz_started", "question_answered", "quiz_abandoned", "quiz_completed", "email_captured", "product_clicked", "added_to_cart", "purchase"]),
  quizId: z.string().optional(),
  sessionId: z.string().optional(),
