const PRODUCTS_QUERY = `#graphql
  query GetProducts($first: Int!, $after: String, $query: String) {
    products(first: $first, after: $after, query: $query) {
      edges {
        node {
          id title handle status
          featuredImage { url altText }
          tags
          priceRangeV2 { minVariantPrice { amount currencyCode } maxVariantPrice { amount currencyCode } }
          collections(first: 10) { edges { node { id title } } }
          variants(first: 5) { edges { node { id title availableForSale price selectedOptions { name value } } } }
          updatedAt
        }
      }
      pageInfo { hasNextPage endCursor hasPreviousPage startCursor }
    }
  }
`;

async function* paginateProducts(admin: any, queryString = "status:active") {
  let cursor: string | null = null;
  do {
    const { data } = await (await admin.graphql(PRODUCTS_QUERY, { variables: { first: 250, after: cursor, query: queryString } })).json();
    for (const { node } of data.products.edges) yield node;
    cursor = data.products.pageInfo.hasNextPage ? data.products.pageInfo.endCursor : null;
  } while (cursor);
}
