## FILE UPLOAD MUTATION (Shopify Files API)

```typescript
const STAGED_UPLOADS_MUTATION = `#graphql
  mutation stagedUploadsCreate($input: [StagedUploadInput!]!) {
    stagedUploadsCreate(input: $input) {
      stagedTargets { url resourceUrl parameters { name value } }
      userErrors { field message }
    }
  }
`;

async function uploadFile(admin: any, file: { name: string; type: string; size: number; data: Blob }): Promise<string> {
  const { data } = await (await admin.graphql(STAGED_UPLOADS_MUTATION, { variables: { input: [{
    filename: file.name, mimeType: file.type, resource: "FILE", fileSize: String(file.size),
  }]}})).json();
  if (data.stagedUploadsCreate.userErrors.length) throw new Error(data.stagedUploadsCreate.userErrors[0].message);

  const target = data.stagedUploadsCreate.stagedTargets[0];
  const form = new FormData();
  target.parameters.forEach(({ name, value }: { name: string; value: string }) => form.append(name, value));
  form.append("file", file.data);
  const upload = await fetch(target.url, { method: "POST", body: form });
  if (!upload.ok) throw new Error("File upload failed");
  return target.resourceUrl;
}
```

## RATE LIMIT HANDLING

```typescript
async function graphqlWithRetry(admin: any, query: string, variables: object, maxRetries = 3): Promise<any> {
  for (let attempt = 0; attempt < maxRetries; attempt++) {
    const response = await admin.graphql(query, { variables });
    const { data, errors, extensions } = await response.json();

    if (extensions?.cost?.throttleStatus?.currentlyAvailable < 100) {
      // Approaching rate limit — back off
      await new Promise(resolve => setTimeout(resolve, 1000 * (attempt + 1)));
    }
    if (errors?.[0]?.extensions?.code === "THROTTLED") {
      const retryAfter = parseInt(response.headers.get("Retry-After") ?? "1") * 1000;
      await new Promise(resolve => setTimeout(resolve, retryAfter));
      continue;
    }
    return { data, errors };
  }
  throw new Error("GraphQL rate limit exceeded after retries");
}
```

