// Encode/decode Shopify Global IDs
export function parseGid(gid: string): { type: string; id: string } {
  const match = gid.match(/^gid:\/\/shopify\/(\w+)\/(\d+)$/);
  if (!match) throw new Error(`Invalid GID: ${gid}`);
  return { type: match[1], id: match[2] };
}
export function buildGid(type: string, id: string | number): string {
  return `gid://shopify/${type}/${id}`;
}
// Usage: buildGid("Product", "12345") → "gid://shopify/Product/12345"
```

