## SERVER-SIDE VALIDATION IN ACTIONS

```typescript
// Pattern: validate → transform → use
export async function action({ request }: ActionFunctionArgs) {
  const { session } = await authenticate.admin(request);
  const formData = await request.formData();

  // Parse form data
  const rawData = {
    title: formData.get("title"),
    description: formData.get("description"),
    type: formData.get("type"),
  };

  // Validate
  const result = CreateQuizSchema.safeParse(rawData);
  if (!result.success) {
    const fieldErrors = result.error.flatten().fieldErrors;
    return json({ errors: fieldErrors }, { status: 422 });
  }

  const { title, description, type } = result.data;
  // Use validated, transformed data
  await db.quiz.create({ data: { shop: session.shop, title, description, type, slug: await generateSlug(title, session.shop) } });
  return json({ success: true });
}
```

## CLIENT-SIDE ERROR DISPLAY (Polaris)

```tsx
// Display field-level errors from action
function QuizForm() {
  const actionData = useActionData<typeof action>();
  const errors = actionData?.errors ?? {};

  return (
    <Form method="post">
      <FormLayout>
        <TextField
          label="Quiz title"
          name="title"
          autoComplete="off"
          error={errors.title?.[0]}  // Polaris shows error below field
          helpText="Choose a clear, descriptive name for your quiz"
        />
        <Select
          label="Quiz type"
          name="type"
          options={[
            { label: "Product Recommendation", value: "recommendation" },
            { label: "Scored (personality)", value: "scored" },
          ]}
          error={errors.type?.[0]}
        />
        <Button submit variant="primary">Create Quiz</Button>
      </FormLayout>
    </Form>
  );
}
```

## SANITIZATION HELPERS

```typescript
// app/utils/sanitize.ts
export function sanitizeSlug(input: string): string {
  return input.toLowerCase().trim()
    .replace(/[^a-z0-9]+/g, "-")
    .replace(/(^-|-$)/g, "")
    .slice(0, 80);
}

export function sanitizeHex(color: string): string {
  const match = color.match(/^#?([0-9A-Fa-f]{6})$/);
  return match ? `#${match[1].toUpperCase()}` : "#000000";
}

export function sanitizeTags(tags: unknown): string[] {
  if (!Array.isArray(tags)) return [];
  return [...new Set(tags.filter((t): t is string => typeof t === "string" && t.length > 0).map(t => t.toLowerCase().trim()))].slice(0, 50);
}
```

## SELF-VALIDATION CHECKLIST
- [ ] All form actions use Zod safeParse (not parse — never throws)
- [ ] Field errors returned as { errors: Record<string, string[]> }
- [ ] Polaris TextField receives error prop from actionData
- [ ] Slugs sanitized to [a-z0-9-] before saving
- [ ] Email validation uses z.string().email()
- [ ] Public API schemas are stricter than admin schemas
- [ ] Color inputs validated as hex (#RRGGBB)
- [ ] Array inputs bounded (max length to prevent abuse)
- [ ] npm run typecheck passes on validators.ts

## NEVER
- Never trust formData.get() without validation
- Never use z.parse() in actions — always safeParse to avoid throws
- Never show raw Zod error paths to users — use flatten().fieldErrors
- Never skip sanitization on user-provided slugs or CSS
