## DECISION TREE
```
Task received
├── "add field" → edit schema.prisma → migrate dev → prisma generate → typecheck
├── "new model" → design full model → add to schema → migrate → update relations
├── "slow query" → analyze query → add index → measure improvement
├── "N+1 query" → add include/select → batch with $transaction
├── "unique constraint" → add @@unique → handle P2002 errors with upsert
└── Always run typecheck after any schema change
```

## SPAWN AGENTS
- `bug-fixer` → if migration fails or TypeScript errors after schema change
- `admin-builder` → if new model needs admin UI routes
- `api-builder` → if new model needs public API endpoints

## MIGRATION WORKFLOW (Always Follow This Order)

```bash
1. Edit prisma/schema.prisma
2. npx prisma migrate dev --name descriptive_name   # Creates migration + applies
3. npx prisma generate                               # Updates TypeScript types
4. npm run typecheck                                 # Fix any type errors from new fields
5. Update any route files referencing changed models
```

## COMPLETE QUIZSNAP SCHEMA (Canonical Reference)

```prisma
// prisma/schema.prisma
datasource db {
  provider = "sqlite"  // Change to "postgresql" for production
  url      = env("DATABASE_URL")
}
generator client { provider = "prisma-client-js" }

// Shopify session storage — DO NOT MODIFY
model Session {
  id                      String    @id
  shop                    String
  state                   String
  isOnline                Boolean   @default(false)
  scope                   String?
  expires                 DateTime?
  accessToken             String
  userId                  BigInt?
  firstName               String?
  lastName                String?
  email                   String?
  accountOwner            Boolean   @default(false)
  locale                  String?
  collaborator            Boolean?  @default(false)
  emailVerified           Boolean?  @default(false)
}

model Quiz {
  id          String    @id @default(cuid())
  shop        String
  title       String
  description String?
  slug        String
  status      String    @default("draft")         // draft|active|paused|archived
  type        String    @default("recommendation") // recommendation|scored|personality
  settings    String    @default("{}")             // JSON: showProgressBar, allowBack, shuffleQuestions, requireEmail
  styling     String    @default("{}")             // JSON: primaryColor, fontFamily, borderRadius, bgColor
  completions Int       @default(0)
  startCount  Int       @default(0)
  publishedAt DateTime?
  questions   Question[]
  resultPages ResultPage[]
  analytics   AnalyticsEvent[]
  abTests     ABTest[]
  responses   QuizResponse[]
  createdAt   DateTime  @default(now())
  updatedAt   DateTime  @updatedAt
  @@unique([shop, slug])
  @@index([shop, status])
  @@index([shop, updatedAt])
}

model Question {
  id          String   @id @default(cuid())
  quizId      String
  quiz        Quiz     @relation(fields: [quizId], references: [id], onDelete: Cascade)
  type        String   // multiple-choice|image-choice|slider|text-input|email|date|dropdown|rating
  title       String
  description String?
  imageUrl    String?
  required    Boolean  @default(true)
  position    Int
  settings    String   @default("{}") // JSON: type-specific settings
  logic       String   @default("[]") // JSON: LogicRule[]
  answers     Answer[]
  createdAt   DateTime @default(now())
  updatedAt   DateTime @updatedAt
  @@index([quizId, position])
}

model Answer {
  id             String   @id @default(cuid())
  questionId     String
  question       Question @relation(fields: [questionId], references: [id], onDelete: Cascade)
  text           String
  imageUrl       String?
  position       Int
  score          Int      @default(0)
  productTags    String   @default("[]") // JSON: string[] of recommendation tags
  nextQuestionId String?  // Direct branch override
  metadata       String   @default("{}")
  createdAt      DateTime @default(now())
  updatedAt      DateTime @updatedAt
  @@index([questionId, position])
}

model ResultPage {
  id           String   @id @default(cuid())
  quizId       String
  quiz         Quiz     @relation(fields: [quizId], references: [id], onDelete: Cascade)
  title        String
  description  String?
  type         String   @default("default") // default|score-range|tag-match
  minScore     Int?
  maxScore     Int?
  matchTags    String   @default("[]")      // JSON: tags that route here
  productLimit Int      @default(4)
  layout       String   @default("grid")    // grid|list|carousel
  showDiscount Boolean  @default(false)
  discountType String?  // percentage|fixed
  discountValue Float?
  discountCode String?
  ctaText      String   @default("Add to Cart")
  ctaUrl       String?
  styling      String   @default("{}")
  position     Int      @default(0)
  createdAt    DateTime @default(now())
  updatedAt    DateTime @updatedAt
  @@index([quizId, position])
}

model QuizResponse {
  id                   String    @id @default(cuid())
  quizId               String
  quiz                 Quiz      @relation(fields: [quizId], references: [id], onDelete: Cascade)
  shop                 String
  sessionId            String
  email                String?
  answers              String    @default("{}") // JSON: questionId → answerId/value
  score                Int?
  recommendedProducts  String    @default("[]") // JSON: productGid[]
  completedAt          DateTime?
  convertedAt          DateTime?
  revenue              Float     @default(0)
  source               String?   // embed|popup|link|email
  deviceType           String?   // mobile|tablet|desktop
  createdAt            DateTime  @default(now())
  updatedAt            DateTime  @updatedAt
  @@index([quizId, shop])
  @@index([shop, createdAt])
  @@index([email])
}

model ProductMapping {
  id          String   @id @default(cuid())
