```typescript
// app/services/results.server.ts
export async function findResultPage(
  quiz: { resultPages: ResultPage[] },
  score: number,
  responseTags: string[]
): Promise<ResultPage> {
  const pages = [...quiz.resultPages].sort((a, b) => a.position - b.position);

  for (const page of pages) {
    if (page.type === "score-range") {
      const min = page.minScore ?? 0;
      const max = page.maxScore ?? Infinity;
      if (score >= min && score <= max) return page;
    }
    if (page.type === "tag-match") {
      const matchTags = JSON.parse(page.matchTags) as string[];
      const hasMatch = matchTags.some(tag => responseTags.includes(tag));
      if (hasMatch) return page;
    }
  }
  // Default: return first result page (always create a default)
  const defaultPage = pages.find(p => p.type === "default") ?? pages[0];
  if (!defaultPage) throw new Error("Quiz has no result pages — create at least one");
  return defaultPage;
}
```

