## TEMPLATE INSTANTIATION (One Click → Full Quiz)

```typescript
// app/services/template.server.ts
export async function instantiateTemplate(templateId: string, shop: string, db: PrismaClient): Promise<string> {
  const template = await db.quizTemplate.findUnique({ where: { id: templateId } });
  if (!template) throw new Error("Template not found");

  const data: TemplateData = JSON.parse(template.templateData);
  let slug = data.quiz.title.toLowerCase().replace(/[^a-z0-9]+/g, "-").replace(/(^-|-$)/g, "");
  let counter = 2;
  while (await db.quiz.findFirst({ where: { shop, slug } })) { slug = `${slug}-${counter++}`; }

  const quiz = await db.$transaction(async (tx) => {
    const newQuiz = await tx.quiz.create({ data: {
      shop, title: data.quiz.title, description: data.quiz.description,
      slug, status: "draft", type: data.quiz.type,
      settings: JSON.stringify(data.quiz.settings), styling: JSON.stringify(data.quiz.styling),
    }});
    for (const q of data.questions) {
      const question = await tx.question.create({ data: {
        quizId: newQuiz.id, type: q.type as QuestionType, title: q.title,
        description: q.description, required: q.required, position: q.position,
        settings: JSON.stringify(q.settings), logic: "[]",
      }});
      if (q.answers?.length) {
        await tx.answer.createMany({ data: q.answers.map(a => ({
          questionId: question.id, text: a.text, imageUrl: a.imageUrl ?? null,
          position: a.position, score: a.score, productTags: JSON.stringify(a.productTags), metadata: "{}",
        }))});
      }
    }
    for (const rp of data.resultPages) {
      await tx.resultPage.create({ data: {
        quizId: newQuiz.id, title: rp.title, description: rp.description ?? null,
        type: rp.type, minScore: rp.minScore ?? null, maxScore: rp.maxScore ?? null,
        matchTags: JSON.stringify(rp.matchTags ?? []), productLimit: rp.productLimit,
        layout: rp.layout, ctaText: rp.ctaText, position: rp.position,
      }});
    }
    await tx.quizTemplate.update({ where: { id: templateId }, data: { usageCount: { increment: 1 } } });
    return newQuiz;
  });
  return quiz.id;
}
```

