## 3 SCORING MODES

```typescript
// app/utils/scoring.ts

// Mode 1: TAG-MATCH — best for product recommendations
// Each answer has productTags, accumulate all selected tags, match against products
export function calculateTagScore(answerProductTags: string[][], quizType = "recommendation"): string[] {
  const tagCounts: Record<string, number> = {};
  answerProductTags.flat().forEach(tag => { tagCounts[tag] = (tagCounts[tag] ?? 0) + 1; });
  return Object.entries(tagCounts).sort(([,a], [,b]) => b - a).map(([tag]) => tag);
}

// Mode 2: POINT-BASED — best for scored/personality quizzes
// Each answer has a score value, accumulate total
export function calculatePointScore(
  responses: Record<string, string | string[] | number>,
  questions: Array<{ id: string; answers: Array<{ id: string; score: number; }> }>
): number {
  let total = 0;
  for (const question of questions) {
    const response = responses[question.id];
    const answerIds = Array.isArray(response) ? response : [String(response)];
    for (const answerId of answerIds) {
      const answer = question.answers.find(a => a.id === answerId);
      if (answer) total += answer.score;
    }
  }
  return total;
}

// Mode 3: HYBRID — tag matching + base scores on products
// Use in recommendation engine: tagScore + product.baseScore

// Route to result page by score range
export function routeByScore(score: number, resultPages: Array<{ type: string; minScore: number | null; maxScore: number | null; position: number }>): number {
  for (const page of resultPages.sort((a, b) => a.position - b.position)) {
    if (page.type === "score-range") {
      const min = page.minScore ?? -Infinity;
      const max = page.maxScore ?? Infinity;
      if (score >= min && score <= max) return resultPages.indexOf(page);
    }
  }
  return 0; // Default to first page
}
```

## TIE-BREAKING ALGORITHM

```typescript
// When 2+ products have equal score, use secondary criteria:
function tieBreak(a: ScoredProduct, b: ScoredProduct): number {
  if (b.totalScore !== a.totalScore) return b.totalScore - a.totalScore;          // 1. Higher score first
  if (b.matchPercentage !== a.matchPercentage) return b.matchPercentage - a.matchPercentage; // 2. Better match %
  if (a.priceMin !== b.priceMin) return a.priceMin - b.priceMin;                  // 3. Lower price first
  return a.title.localeCompare(b.title);                                            // 4. Alphabetical
}
```

## SELF-VALIDATION CHECKLIST
- [ ] Tag comparison is case-insensitive
- [ ] Score accumulation handles multi-select questions (sum all selected answer scores)
- [ ] Fallback result page exists (score out of all ranges → first page)
- [ ] Tag deduplication (same tag from multiple answers counted once for routing)
- [ ] Zero-score edge case handled (return fallback products)
- [ ] TypeScript types for ScoredProduct are complete

## NEVER
- Never return empty recommendations — always use fallback
- Never compare tags case-sensitively
- Never route to a result page that doesn't exist
