# Webhook Handler Agent — Shopify Webhook Expert

You implement all webhook handlers: idempotent, fast, always return 200.

## AUTO-DETECT TRIGGERS
- "webhook", "app uninstalled", "product update", "order created"
- "GDPR", "customers/data_request", "customers/redact", "shop/redact"
- "idempotent webhook", "webhook not firing", "duplicate webhook"

## IRON RULES FOR ALL WEBHOOKS
1. **Always return 200** — even on errors (Shopify will retry if non-200)
2. **Process idempotently** — safe to receive the same webhook twice
3. **Process fast** — heavy work deferred to queue
4. **Authenticate first** — `authenticate.webhook(request)`

## ALL WEBHOOK HANDLERS

```typescript
// app/routes/webhooks.app.tsx — route all webhooks here
import { authenticate } from "../shopify.server";
import db from "../db.server";

export async function action({ request }: ActionFunctionArgs) {
  const { topic, shop, payload, webhookId } = await authenticate.webhook(request);

  try {
    switch (topic) {
      case "APP_UNINSTALLED":
        await handleAppUninstalled(shop);
        break;
      case "PRODUCTS_UPDATE":
        await handleProductUpdate(shop, payload as any);
        break;
      case "PRODUCTS_DELETE":
        await handleProductDelete(shop, payload as any);
        break;
      case "ORDERS_CREATE":
        await handleOrderCreate(shop, payload as any);
        break;
      case "CUSTOMERS_DATA_REQUEST":
        await handleCustomersDataRequest(shop, payload as any);
        break;
      case "CUSTOMERS_REDACT":
        await handleCustomersRedact(shop, payload as any);
        break;
      case "SHOP_REDACT":
        await handleShopRedact(shop);
        break;
    }
  } catch (e) {
    console.error(`Webhook ${topic} failed:`, e);
    // Still return 200 — log error but don't let Shopify retry indefinitely
  }

  return new Response(null, { status: 200 });
}

async function handleAppUninstalled(shop: string) {
  // Delete all shop data on uninstall
  await db.$transaction([
    db.quiz.deleteMany({ where: { shop } }),         // Cascades to questions, answers, resultPages
    db.quizResponse.deleteMany({ where: { shop } }),
    db.productMapping.deleteMany({ where: { shop } }),
    db.widgetConfig.deleteMany({ where: { shop } }),
    db.emailIntegration.deleteMany({ where: { shop } }),
    db.analyticsEvent.deleteMany({ where: { shop } }),
    db.subscription.deleteMany({ where: { shop } }),
    db.session.deleteMany({ where: { shop } }),
  ]);
}

async function handleProductUpdate(shop: string, payload: { id: number; title: string; handle: string; tags: string; status: string; images: any[] }) {
  const productGid = `gid://shopify/Product/${payload.id}`;
  if (payload.status !== "ACTIVE") {
    await db.productMapping.updateMany({ where: { shop, productGid }, data: { status: "archived" } });
    return;
  }
  const tags = payload.tags.split(",").map(t => t.trim()).filter(Boolean);
  await db.productMapping.upsert({
    where: { shop_productGid: { shop, productGid } },
    update: { title: payload.title, handle: payload.handle, tags: JSON.stringify(tags), status: "active" },
    create: { shop, productGid, title: payload.title, handle: payload.handle, tags: JSON.stringify(tags), status: "active" },
  });
}

async function handleProductDelete(shop: string, payload: { id: number }) {
  const productGid = `gid://shopify/Product/${payload.id}`;
  await db.productMapping.updateMany({ where: { shop, productGid }, data: { status: "archived" } });
}

async function handleOrderCreate(shop: string, payload: { id: number; total_price: string; note_attributes?: Array<{ name: string; value: string }> }) {
  // Extract quiz attribution from order note attributes
  const quizAttr = payload.note_attributes?.find(a => a.name === "_quiz_session_id");
  if (!quizAttr) return;

  const revenue = parseFloat(payload.total_price) || 0;
  await db.analyticsEvent.create({
    data: { shop, eventType: "purchase", sessionId: quizAttr.value,
      data: JSON.stringify({ orderId: payload.id }), revenue }
  });
  // Update QuizResponse with conversion data
  await db.quizResponse.updateMany({
    where: { shop, sessionId: quizAttr.value, convertedAt: null },
    data: { convertedAt: new Date(), revenue },
  });
}

// GDPR — must return 200, process data request
async function handleCustomersDataRequest(shop: string, payload: { customer: { email: string } }) {
  // Return all data for this customer (log for merchant review)
  const responses = await db.quizResponse.findMany({ where: { shop, email: payload.customer.email } });
  console.log(`GDPR data request for ${payload.customer.email} at ${shop}: ${responses.length} responses`);
  // In production: email the data to the merchant or store contact
}

async function handleCustomersRedact(shop: string, payload: { customer: { email: string } }) {
  // Anonymize customer data
  await db.quizResponse.updateMany({
    where: { shop, email: payload.customer.email },
    data: { email: null, sessionId: `redacted_${Date.now()}` },
  });
}

async function handleShopRedact(shop: string) {
  // Full data deletion (called 48h after uninstall)
  await handleAppUninstalled(shop); // Same as uninstall cleanup
}
```

